#!/bin/bash
# ============================================================
#  L2TP/IPsec VPN + Farsi Web Panel  -  one-shot installer
#  Features: per-user traffic quota, time-limit (expiry),
#            single-session, bandwidth shaping, HTTPS panel.
#  Usage:  sudo bash install.sh
# ============================================================
set -e
[ "$(id -u)" -eq 0 ] || { echo "لطفاً با روت (sudo) اجرا کنید"; exit 1; }

echo "==================================================="
echo "        نصب پنل و سرور L2TP VPN"
echo "==================================================="
read -rp "دامنه پنل (مثال l2tp.example.com): " DOMAIN
read -rp "ایمیل برای گواهی SSL: " EMAIL
read -rp "نام کاربری ورود به پنل: " PANEL_USER
read -rsp "رمز عبور ورود به پنل: " PANEL_PASS; echo
read -rp "کلید مشترک IPsec (PSK): " VPN_PSK
read -rp "اولین کاربر VPN (نام کاربری): " V1USER
read -rsp "رمز اولین کاربر VPN: " V1PASS; echo
read -rp "پورت داخلی پنل [8088]: " PANEL_PORT; PANEL_PORT=${PANEL_PORT:-8088}
DL_LIMIT="200mbit"; UL_LIMIT="20mbit"
export DEBIAN_FRONTEND=noninteractive

echo ">> نصب L2TP/IPsec (hwdsl2)..."
wget -qO /tmp/vpnsetup.sh https://raw.githubusercontent.com/hwdsl2/setup-ipsec-vpn/master/vpnsetup.sh
VPN_IPSEC_PSK="$VPN_PSK" VPN_USER="$V1USER" VPN_PASSWORD="$V1PASS" sh /tmp/vpnsetup.sh >/tmp/vpnsetup.log 2>&1 || true

echo ">> نصب nginx / certbot / ابزارها..."
apt-get update -qq
apt-get -yqq install nginx certbot python3-certbot-nginx iproute2 >/dev/null

echo ">> ساخت مسیرها..."
mkdir -p /var/lib/vpnstat /run/vpn-online /run/vpn-blocked
[ -f /var/lib/vpnstat/usage.json ] || echo "{}" > /var/lib/vpnstat/usage.json
[ -f /var/lib/vpnstat/meta.json ]  || echo "{}" > /var/lib/vpnstat/meta.json

echo ">> اسکریپت محدودیت پهنای‌باند..."
cat > /etc/ppp/ip-up.d/50-ratelimit <<RL
#!/bin/bash
IF="\$1"; [ -z "\$IF" ] && exit 0
tc qdisc del dev "\$IF" root 2>/dev/null
tc qdisc add dev "\$IF" root handle 1: htb default 10
tc class add dev "\$IF" parent 1: classid 1:10 htb rate ${DL_LIMIT} ceil ${DL_LIMIT}
tc qdisc del dev "\$IF" ingress 2>/dev/null
tc qdisc add dev "\$IF" handle ffff: ingress
tc filter add dev "\$IF" parent ffff: protocol ip u32 match u32 0 0 police rate ${UL_LIMIT} burst 200k mtu 64kb drop flowid :1
exit 0
RL
chmod +x /etc/ppp/ip-up.d/50-ratelimit

echo ">> گارد تک‌نشست و بلاک..."
cat > /etc/ppp/ip-up.d/20-vpnguard <<'GUARD'
#!/bin/bash
IF="$1"; USER="$PEERNAME"; PID="$PPID"
[ -z "$USER" ] && exit 0
mkdir -p /run/vpn-online /run/vpn-blocked
[ -f "/run/vpn-blocked/$USER" ] && { kill "$PID" 2>/dev/null; exit 0; }
for f in /run/vpn-online/*; do
  [ -e "$f" ] || continue
  [ "$f" = "/run/vpn-online/$IF" ] && continue
  if [ "$(head -1 "$f")" = "$USER" ]; then
    opid=$(sed -n 2p "$f" | awk "{print \$2}")
    [ -n "$opid" ] && kill "$opid" 2>/dev/null
    rm -f "$f"
  fi
done
printf "%s\n%s %s\n" "$USER" "$(date +%s)" "$PID" > "/run/vpn-online/$IF"
exit 0
GUARD
chmod +x /etc/ppp/ip-up.d/20-vpnguard

echo ">> حساب‌داری مصرف..."
cat > /etc/ppp/ip-down.d/60-acct <<'ACCT'
#!/bin/bash
IF="$1"; USER="$PEERNAME"
[ -z "$USER" ] && [ -f "/run/vpn-online/$IF" ] && USER="$(head -1 /run/vpn-online/$IF)"
[ -z "$USER" ] && exit 0
python3 - "$USER" "${BYTES_RCVD:-0}" "${BYTES_SENT:-0}" <<PY
import json,sys,fcntl
u,rx,tx=sys.argv[1],int(sys.argv[2]),int(sys.argv[3])
p="/var/lib/vpnstat/usage.json"
f=open(p,"a+"); fcntl.flock(f,fcntl.LOCK_EX); f.seek(0)
try: d=json.load(f)
except: d={}
e=d.get(u,{"rx":0,"tx":0}); e["rx"]+=rx; e["tx"]+=tx; d[u]=e
f.seek(0); f.truncate(); json.dump(d,f)
PY
rm -f "/run/vpn-online/$IF"
exit 0
ACCT
chmod +x /etc/ppp/ip-down.d/60-acct

echo ">> بهبود پایداری pppd + MSS clamp..."
sed -i "s/^lcp-echo-interval.*/lcp-echo-interval 20/;s/^lcp-echo-failure.*/lcp-echo-failure 30/" /etc/ppp/options.xl2tpd 2>/dev/null || true
iptables -t mangle -C FORWARD -p tcp --tcp-flags SYN,RST SYN -o ppp+ -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || \
iptables -t mangle -A FORWARD -p tcp --tcp-flags SYN,RST SYN -o ppp+ -j TCPMSS --clamp-mss-to-pmtu
iptables -t mangle -C FORWARD -p tcp --tcp-flags SYN,RST SYN -i ppp+ -j TCPMSS --clamp-mss-to-pmtu 2>/dev/null || \
iptables -t mangle -A FORWARD -p tcp --tcp-flags SYN,RST SYN -i ppp+ -j TCPMSS --clamp-mss-to-pmtu
netfilter-persistent save 2>/dev/null || true

echo ">> نصب پنل..."
echo "" | base64 -d > /usr/local/bin/vpn-panel.py
echo "" | base64 -d > /usr/local/bin/vpn-enforce.py
python3 - "$PANEL_USER" "$PANEL_PASS" "$PANEL_PORT" <<'PY'
import sys
u,p,port=sys.argv[1],sys.argv[2],sys.argv[3]
s=open("/usr/local/bin/vpn-panel.py").read()
s=s.replace("__PANEL_USER__",u).replace("__PANEL_PASS__",p)
s=s.replace('("127.0.0.1",8088)','("127.0.0.1",%s)'%port)
open("/usr/local/bin/vpn-panel.py","w").write(s)
PY
chmod +x /usr/local/bin/vpn-panel.py /usr/local/bin/vpn-enforce.py

cat > /etc/systemd/system/vpn-panel.service <<EOF
[Unit]
Description=VPN Web Panel
After=network.target
[Service]
ExecStart=/usr/bin/python3 /usr/local/bin/vpn-panel.py
Restart=always
User=root
[Install]
WantedBy=multi-user.target
EOF
cat > /etc/systemd/system/vpn-enforce.service <<EOF
[Unit]
Description=VPN quota/time enforcement
After=network.target
[Service]
ExecStart=/usr/bin/python3 /usr/local/bin/vpn-enforce.py
Restart=always
User=root
[Install]
WantedBy=multi-user.target
EOF
systemctl daemon-reload
systemctl enable --now vpn-panel vpn-enforce >/dev/null 2>&1

echo ">> پیکربندی nginx + SSL..."
cat > /etc/nginx/sites-available/vpnpanel <<EOF
server {
    listen 80;
    server_name ${DOMAIN};
    location / {
        proxy_pass http://127.0.0.1:${PANEL_PORT};
        proxy_set_header Host \$host;
        proxy_set_header X-Real-IP \$remote_addr;
    }
}
EOF
ln -sf /etc/nginx/sites-available/vpnpanel /etc/nginx/sites-enabled/vpnpanel
rm -f /etc/nginx/sites-enabled/default
nginx -t && systemctl restart nginx
certbot --nginx -d "$DOMAIN" --non-interactive --agree-tos -m "$EMAIL" --redirect || \
  echo "!! دریافت SSL ناموفق بود؛ دامنه باید به این سرور اشاره کند و پورت 80/443 باز باشد."

echo ""
echo "==================================================="
echo "  ✅ نصب کامل شد"
echo "  پنل : https://$DOMAIN"
echo "  ورود: $PANEL_USER"
echo "  PSK : $VPN_PSK"
echo "  پورت‌های UDP 500/4500 و TCP 80/443 را در فایروال باز کنید."
echo "==================================================="
